#!/usr/bin/env python3
"""bake.py – Plan-renderer bake step. Self-contained.

Reads a Plan-Contract markdown plan and its optional progress.json overlay,
and writes a single self-contained HTML file next to the plan. All assets
(HTML template, renderer JS, both stylesheets) are embedded as Python string
constants in this file – no sibling files needed at runtime. The deployed
agents only need this one script.

Usage:
    python bake.py [--plan path/to/plan.md] [--progress path/to/progress.json] [--out path/to/out.html]

Defaults: progress = <plan>.progress.json, out = <plan>.html, both next to the plan.

To refresh the embedded assets after editing the source files, run pack.py in
the source repo next to this script. Do NOT hand-edit the marker blocks
below.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve().parent


