# >>> PACK styles.css >>>
STYLES_CSS = '/* plan-renderer component styles – all colours sourced from the\n   black-silver palette role variables. Light/dark switch via\n   [data-omnis-mode="dark"] on <html>. */\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  margin: 0;\n  padding: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n::selection { background: var(--selection-bg); }\n:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }\n\na { color: var(--accent); }\ncode { background: var(--surface); padding: 0 .25em; border-radius: 3px; }\n\n/* ─── App chrome ──────────────────────────────────────────────── */\n\n.app-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 12px 24px;\n  background: var(--sidebar);\n  color: var(--on-sidebar);\n  border-bottom: 1px solid var(--border);\n}\n.app-bar .app-title {\n  font-weight: 600;\n  font-size: 16px;\n  letter-spacing: .02em;\n  color: var(--on-sidebar-active);\n}\n.app-bar .controls { display: flex; gap: 8px; }\n\nmain {\n  padding: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n/* ─── Cards ───────────────────────────────────────────────────── */\n\n.card {\n  background: var(--card);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 16px 20px;\n  box-shadow: var(--shadow-soft);\n}\n.card h2 {\n  margin: 0 0 12px;\n  font-size: 15px;\n  font-weight: 600;\n  letter-spacing: .02em;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--text);\n}\n\n.plan-header { padding: 16px 20px; }\n.plan-intro {\n  margin: 0;\n  color: var(--muted);\n  font-size: 13px;\n}\n.phase-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 12px;\n}\n\n.card-flow { padding: 12px 16px; }\n.card-flow pre.mermaid,\n.card-flow .mermaid-rendered {\n  background: var(--surface);\n  border-radius: 6px;\n  padding: 12px;\n  overflow-x: auto;\n  display: flex;\n  justify-content: center;\n}\n.mermaid-rendered svg { max-width: 100%; height: auto; }\n\n/* ─── Phase chips ─────────────────────────────────────────────── */\n\n.chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 2px 10px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 500;\n  border: 1px solid transparent;\n  background: var(--state-pending-bg);\n  color: var(--state-pending-text);\n  border-color: var(--state-pending-border);\n  text-transform: lowercase;\n  letter-spacing: .02em;\n}\n.chip-dot {\n  width: 8px; height: 8px;\n  border-radius: 50%;\n  background: currentColor;\n}\n.chip-tiny {\n  padding: 0 8px;\n  font-size: 11px;\n  height: 18px;\n  line-height: 18px;\n}\n\n.chip-pending,\n.chip-pending .chip-dot { color: var(--state-pending-text); }\n.chip-pending { background: var(--state-pending-bg); border-color: var(--state-pending-border); }\n\n.chip-current,\n.chip-current .chip-dot { color: var(--state-active-text); }\n.chip-current { background: var(--state-active-bg); border-color: var(--state-active-border); }\n\n.chip-in-progress,\n.chip-in-progress .chip-dot { color: var(--state-active-text); }\n.chip-in-progress { background: var(--state-active-bg); border-color: var(--state-active-border); }\n\n.chip-under-review,\n.chip-under-review .chip-dot { color: var(--state-terminal-text); }\n.chip-under-review { background: var(--state-terminal-bg); border-color: var(--state-terminal-border); }\n\n.chip-needs-fixes,\n.chip-needs-fixes .chip-dot { color: var(--state-blocked-text); }\n.chip-needs-fixes { background: var(--state-blocked-bg); border-color: var(--state-blocked-border); }\n\n.chip-blocked,\n.chip-blocked .chip-dot { color: var(--state-blocked-text); }\n.chip-blocked { background: var(--state-blocked-bg); border-color: var(--state-blocked-border); }\n\n.chip-completed,\n.chip-completed .chip-dot,\n.chip-done,\n.chip-done .chip-dot { color: var(--state-completed-text); }\n.chip-completed, .chip-done {\n  background: var(--state-completed-bg);\n  border-color: var(--state-completed-border);\n}\n\n/* ─── Phase cards ─────────────────────────────────────────────── */\n\n.phases { display: flex; flex-direction: column; gap: 12px; }\n\n.phase {\n  padding: 0;\n  overflow: hidden;\n  border-left: 3px solid var(--border-strong);\n}\n.phase-current { border-left-color: var(--state-active-border); }\n.phase-completed { border-left-color: var(--state-completed-border); }\n.phase-pending { border-left-color: var(--state-pending-border); }\n.phase-under-review { border-left-color: var(--state-terminal-border); }\n.phase-needs-fixes { border-left-color: var(--state-blocked-border); }\n\n.phase-head {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 14px 20px;\n  cursor: pointer;\n  user-select: none;\n}\n.phase-head:hover { background: var(--surface); }\n.phase-num {\n  font-family: ui-monospace, monospace;\n  font-size: 12px;\n  color: var(--muted);\n  letter-spacing: .04em;\n}\n.phase-title {\n  flex: 1;\n  font-weight: 500;\n  font-size: 14px;\n  color: var(--text);\n}\n\n.phase-body {\n  padding: 0 20px 20px;\n  border-top: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n.phase.collapsed .phase-body { display: none; }\n.phase.collapsed .phase-head { border-top: none; }\n\n.phase-intro {\n  margin: 12px 0 0;\n  color: var(--muted);\n  font-size: 13px;\n}\n.phase-intro-block {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.phase-intro-block pre.mermaid,\n.phase-intro-block .mermaid-rendered {\n  background: var(--surface);\n  border-radius: 6px;\n  padding: 12px;\n  overflow-x: auto;\n  display: flex;\n  justify-content: center;\n}\n.phase-intro-block pre.code-block {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 10px 12px;\n  overflow-x: auto;\n  font-size: 12px;\n  font-family: ui-monospace, monospace;\n  margin: 0;\n}\n.phase-intro-block pre.code-block code { background: transparent; padding: 0; }\n\n.phase-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n}\n@media (max-width: 720px) {\n  .phase-grid { grid-template-columns: 1fr; }\n}\n\n/* ─── Items (Work / Files / Acceptance) ───────────────────────── */\n\n.items-label {\n  margin: 0 0 6px;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: .06em;\n  text-transform: uppercase;\n  color: var(--muted);\n}\n.items-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.items-empty {\n  margin: 0;\n  color: var(--dim);\n  font-size: 13px;\n}\n\n.item {\n  display: grid;\n  grid-template-columns: 14px 32px 1fr auto;\n  align-items: start;\n  gap: 8px;\n  padding: 6px 8px;\n  border-radius: 4px;\n}\n.item:hover { background: var(--surface); }\n.item-state-dot {\n  width: 8px; height: 8px;\n  border-radius: 50%;\n  margin-top: 6px;\n  background: var(--state-pending-text);\n  opacity: .6;\n}\n.item-pending .item-state-dot { background: var(--state-pending-text); opacity: .35; }\n.item-in-progress .item-state-dot { background: var(--state-active-text); animation: pulse 1.6s ease-in-out infinite; }\n.item-done .item-state-dot { background: var(--state-completed-text); opacity: 1; }\n.item-blocked .item-state-dot { background: var(--state-blocked-text); opacity: 1; }\n\n@keyframes pulse {\n  0%, 100% { opacity: .55; transform: scale(1); }\n  50%      { opacity: 1;   transform: scale(1.25); }\n}\n\n.item-id {\n  font-family: ui-monospace, monospace;\n  font-size: 11px;\n  color: var(--muted);\n  padding-top: 2px;\n}\n.item-text {\n  font-size: 13px;\n  color: var(--text);\n}\n.item-done .item-text { color: var(--muted); }\n.item-note {\n  display: block;\n  font-size: 11px;\n  color: var(--accent);\n  margin-top: 2px;\n  font-style: italic;\n}\n\n/* ─── Live panel (in-current-phase only) ──────────────────────── */\n\n.live-panel {\n  margin-top: 16px;\n  background: var(--surface);\n  border: 1px solid var(--state-active-border);\n  border-radius: 6px;\n  padding: 12px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.live-head {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.live-label {\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-transform: uppercase;\n  color: var(--state-active-text);\n}\n.live-sub {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 16px;\n  font-size: 12px;\n}\n.live-meta { display: inline-flex; align-items: baseline; gap: 6px; }\n.live-meta-k {\n  font-size: 10px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--dim);\n}\n.live-substate {\n  font-weight: 600;\n  font-family: ui-monospace, monospace;\n  color: var(--state-active-text);\n}\n\n.activity-log {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-family: ui-monospace, monospace;\n  font-size: 11.5px;\n  max-height: 220px;\n  overflow-y: auto;\n}\n.activity {\n  display: grid;\n  grid-template-columns: 50px 110px 1fr;\n  gap: 8px;\n  padding: 3px 0;\n  border-bottom: 1px dashed var(--border);\n}\n.activity:last-child { border-bottom: none; }\n.activity-time { color: var(--dim); }\n.activity-role {\n  font-weight: 600;\n  letter-spacing: .02em;\n  text-transform: lowercase;\n}\n.activity-implementer .activity-role { color: var(--accent); }\n.activity-inner-review .activity-role { color: var(--state-active-text); }\n.activity-reviewer .activity-role { color: var(--state-terminal-text); }\n.activity-msg { color: var(--text); }\n\n/* Proposed decisions */\n.proposed-decisions {\n  border-top: 1px solid var(--border);\n  padding-top: 10px;\n  margin-top: 4px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.proposed-label {\n  font-size: 11px;\n  letter-spacing: .04em;\n  color: var(--muted);\n}\n.proposed-card {\n  background: var(--card);\n  border: 1px dashed var(--accent);\n  border-radius: 4px;\n  padding: 8px 12px;\n}\n.proposed-text { margin: 0 0 4px; font-size: 13px; }\n.proposed-just { margin: 0; font-size: 11.5px; color: var(--muted); font-style: italic; }\n\n/* ─── Decisions cards ─────────────────────────────────────────── */\n\n.decisions-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\n  gap: 10px;\n}\n.decision-card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 10px 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n.decision-title {\n  font-weight: 600;\n  font-size: 13px;\n  color: var(--text);\n}\n.decision-body {\n  margin: 0;\n  font-size: 12px;\n  color: var(--muted);\n  line-height: 1.45;\n}\n.decisions-tools {\n  margin-top: 12px;\n  display: flex;\n  gap: 8px;\n}\n\n/* ─── Footer (open Q + risks) ─────────────────────────────────── */\n\n.footer-sections {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n}\n@media (max-width: 720px) {\n  .footer-sections { grid-template-columns: 1fr; }\n}\n.card-half h2 { margin-bottom: 8px; }\n.card-half ul { margin: 0 0 12px 18px; padding: 0; }\n.card-half li { font-size: 13px; margin-bottom: 4px; }\n.muted { color: var(--muted); font-style: italic; font-size: 13px; }\n\n/* ─── Buttons ─────────────────────────────────────────────────── */\n\n.btn {\n  appearance: none;\n  background: var(--accent);\n  color: var(--on-accent);\n  border: 1px solid var(--accent);\n  padding: 4px 10px;\n  font-size: 12px;\n  border-radius: 4px;\n  cursor: pointer;\n  letter-spacing: .02em;\n  font-weight: 500;\n}\n.btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }\n.btn-ghost {\n  background: transparent;\n  color: var(--accent);\n  border-color: var(--border-strong);\n}\n.btn-ghost:hover {\n  background: var(--accent-bg);\n  border-color: var(--accent);\n}\n.actions { display: flex; gap: 6px; flex-wrap: wrap; }\n.phase-actions {\n  display: flex;\n  gap: 6px;\n  flex-wrap: wrap;\n  border-top: 1px solid var(--border);\n  padding-top: 12px;\n}\n\n.badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 1px 8px;\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: .02em;\n}\n.badge-attention {\n  background: var(--state-active-bg);\n  color: var(--state-active-text);\n  border: 1px solid var(--state-active-border);\n}\n\n/* ─── Toast (prompt emit feedback) ────────────────────────────── */\n\n.toast {\n  position: fixed;\n  bottom: 20px;\n  right: 20px;\n  max-width: 480px;\n  background: var(--card);\n  border: 1px solid var(--state-active-border);\n  border-radius: 8px;\n  padding: 14px 16px;\n  box-shadow: var(--shadow-overlay);\n  z-index: 1000;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  transition: opacity .4s ease, transform .4s ease;\n}\n.toast-fade { opacity: 0; transform: translateY(8px); }\n.toast-label {\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n  color: var(--state-active-text);\n  font-weight: 600;\n}\n.toast-prompt {\n  margin: 0;\n  padding: 8px 10px;\n  background: var(--surface);\n  border-radius: 4px;\n  font-size: 12px;\n  font-family: ui-monospace, monospace;\n  white-space: pre-wrap;\n  max-height: 160px;\n  overflow-y: auto;\n  color: var(--text);\n}\n.toast-close { align-self: flex-end; }\n\n/* ─── Scrollbar ───────────────────────────────────────────────── */\n\n* { scrollbar-width: thin; scrollbar-color: var(--scrollbar-thumb) transparent; }\n*::-webkit-scrollbar { width: 8px; height: 8px; }\n*::-webkit-scrollbar-thumb { background: var(--scrollbar-thumb); border-radius: 4px; }\n*::-webkit-scrollbar-track { background: transparent; }\n'
