# ─── Bake logic ──────────────────────────────────────────────────────────

def parse_args() -> argparse.Namespace:
    ap = argparse.ArgumentParser(
        description="Bake a Plan-Contract markdown plan and its progress.json into a self-contained HTML.",
    )
    ap.add_argument("--plan", type=Path, default=None,
                    help="Path to plan.md.")
    ap.add_argument("--progress", type=Path, default=None,
                    help="Path to progress.json (default: <plan>.progress.json sibling).")
    ap.add_argument("--out", type=Path, default=None,
                    help="Path to output .html (default: <plan>.html sibling).")
    return ap.parse_args()


def resolve_paths(args: argparse.Namespace) -> tuple[Path, Path, Path]:
    if args.plan is None:
        # Local dev fallback: bake the sample plan when one is co-located.
        sample = HERE / "sample" / "implementation-plan.md"
        if sample.exists():
            plan_path = sample.resolve()
        else:
            print("error: --plan is required (no sample/implementation-plan.md next to bake.py).", file=sys.stderr)
            sys.exit(2)
    else:
        plan_path = args.plan.resolve()
    if not plan_path.exists():
        print(f"plan not found: {plan_path}", file=sys.stderr)
        sys.exit(1)
    plan_no_ext = plan_path.with_suffix("")
    progress_path = (args.progress.resolve() if args.progress
                     else plan_no_ext.with_suffix(".progress.json"))
    out_path = args.out.resolve() if args.out else plan_no_ext.with_suffix(".html")
    return plan_path, progress_path, out_path


def esc_for_script_text(s: str) -> str:
    """Break any literal </script that would otherwise close an embedded <script>."""
    return re.sub(r"</(script)", r"<\\/\1", s, flags=re.IGNORECASE)


def bake() -> None:
    args = parse_args()
    plan_path, progress_path, out_path = resolve_paths(args)

    if not INDEX_HTML:
        print("error: bake.py has empty asset constants – run pack.py to populate them.", file=sys.stderr)
        sys.exit(3)

    plan_md = plan_path.read_text(encoding="utf-8")
    progress_json = progress_path.read_text(encoding="utf-8") if progress_path.exists() else ""

    baked_at = datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    progress_label = f" + {progress_path.name}" if progress_json else ""
    bake_banner = f"<!-- baked from {plan_path.name}{progress_label} at {baked_at} -->"

    inline_parts = [
        f'<script id="plan-md" type="text/plain">{esc_for_script_text(plan_md)}</script>',
    ]
    if progress_json:
        inline_parts.append(
            f'<script id="plan-progress" type="application/json">{esc_for_script_text(progress_json)}</script>'
        )
    meta = {
        "baked_at": baked_at,
        "plan": plan_path.name,
        "progress": progress_path.name if progress_json else None,
    }
    inline_parts.append(
        f'<script id="plan-bake-meta" type="application/json">{json.dumps(meta)}</script>'
    )
    inline_data = "\n  ".join(inline_parts)

    def sub_once(pattern: str, replacement: str, src: str, flags: int = 0) -> str:
        return re.sub(pattern, lambda _m: replacement, src, count=1, flags=flags)

    html = INDEX_HTML
    html = sub_once(
        r'<!-- BAKE:CSS-BLACK-SILVER -->\s*<link rel="stylesheet" href="black-silver\.css"\s*/>',
        f'<style id="palette-black-silver">{BLACK_SILVER_CSS}</style>',
        html,
    )
    html = sub_once(
        r'<!-- BAKE:CSS-STYLES -->\s*<link rel="stylesheet" href="styles\.css"\s*/>',
        f'<style id="component-styles">{STYLES_CSS}</style>',
        html,
    )
    html = html.replace("<!-- BAKE:INLINE-DATA -->", inline_data, 1)
    html = sub_once(
        r'<!-- BAKE:RENDERER-JS -->\s*<script src="renderer\.js"></script>',
        f'<script id="renderer-js">{esc_for_script_text(RENDERER_JS)}</script>',
        html,
    )
    html = sub_once(r"<head>", f"<head>\n  {bake_banner}", html, flags=re.IGNORECASE)

    out_path.write_bytes(html.encode("utf-8"))
    print(f"baked: {out_path}")
    print(f"  plan:     {plan_path}")
    print(f"  progress: {progress_path if progress_json else '(none)'}")
    print(f"  size:     {len(html) / 1024:.1f} KiB")


if __name__ == "__main__":
    bake()
